export function summarize() {
  const byStatus: Partial<Record<FigureStatus, number>> = {};
  for (const figure of figures) byStatus[figure.status] = (byStatus[figure.status] ?? 0) + 1;
  return { sources: sources.length, figures: figures.length, byStatus };
}
